import {commerceText} from './commerce-copy.mjs';
export const COSMETICS={theme:['classic','prism','chrome'],effects:['classic','aurora'],motion:['classic','orbit'],sound:['classic','crystal']};
export function normalizeCosmetics(raw={}){return Object.fromEntries(Object.entries(COSMETICS).map(([key,values])=>[key,values.includes(raw?.[key])?raw[key]:'classic']));}
export function setupCommerceUI({commerce,getLanguage,read,write,pause,audio}){
 const dialog=document.createElement('dialog');dialog.id='premium-dialog';dialog.className='panel-dialog premium-dialog';dialog.setAttribute('aria-labelledby','premium-title');
 dialog.innerHTML='<div class="dialog-head"><h2 id="premium-title"></h2></div><p id="premium-details" class="dialog-copy"></p><p id="premium-store-status" role="status" aria-live="polite"></p><div class="premium-actions"><button id="premium-buy" class="primary-button"></button><button id="premium-restore" class="secondary-button"></button></div><div class="premium-cosmetics settings"></div><button id="premium-close" class="primary-button dialog-done"></button>';
 document.body.append(dialog);
 const controls=document.createElement('div');controls.className='commerce-settings';controls.innerHTML='<label class="commerce-age-label"><span id="commerce-age-title"></span><select id="commerce-age"></select></label><p id="commerce-age-copy"></p><button id="premium-open" class="secondary-button"></button><button id="ads-prepare" class="secondary-button"></button><button id="ads-privacy" class="secondary-button" hidden></button><p id="commerce-status" role="status" aria-live="polite"></p>';
 document.querySelector('.settings-links').prepend(controls);
 const $=id=>document.getElementById(id),t=key=>commerceText(getLanguage(),key);let message='',selected=normalizeCosmetics(read('cosmetics',{}));
 for(const value of ['unknown','child','teen','adult']){const option=document.createElement('option');option.value=value;$('commerce-age').append(option);}
 $('commerce-age').addEventListener('change',async()=>{await commerce.request('audience',{age:$('commerce-age').value});message='';refresh();});
 for(const [key,values]of Object.entries(COSMETICS)){const label=document.createElement('label'),span=document.createElement('span'),select=document.createElement('select');span.dataset.cosmeticLabel=key;select.dataset.cosmetic=key;for(const value of values){const option=document.createElement('option');option.value=value;select.append(option);}label.append(span,select);dialog.querySelector('.premium-cosmetics').append(label);select.addEventListener('change',()=>{if(!commerce.state.premium)return;selected[key]=select.value;write('cosmetics',selected);apply();if(key==='sound')audio.effect('earn-bomb');});}
 function apply(){const active=commerce.state.premium?selected:normalizeCosmetics();for(const [key,value]of Object.entries(active))document.documentElement.dataset['cosmetic'+key[0].toUpperCase()+key.slice(1)]=value;audio.cosmeticSound=active.sound;}
 function refresh(){const s=commerce.state;$('commerce-age-title').textContent=t('age');$('commerce-age-copy').textContent=t('ageCopy');$('commerce-age').value=s.age;$('commerce-age').disabled=s.busy||!s.supported;for(const option of $('commerce-age').options)option.textContent=t(option.value);for(const [id,key]of [['premium-title','title'],['premium-details','details'],['premium-restore','restore'],['premium-close','done'],['premium-open','title'],['ads-prepare','prepare'],['ads-privacy','privacy']])$(id).textContent=t(key);$('premium-buy').textContent=s.premium?t('purchased'):s.canPurchase&&s.price?t('buy')+' · '+s.price:t('notForSale');$('premium-buy').disabled=s.busy||s.premium||!s.canPurchase||!s.price;$('premium-restore').disabled=s.busy||!s.supported;$('ads-prepare').disabled=s.busy||!s.supported||s.age!=='adult';$('ads-privacy').hidden=!s.privacyRequired;$('ads-privacy').disabled=s.busy;$('commerce-status').textContent=message?t(message):s.supported?'':t('nativeOnly');$('premium-store-status').textContent=message?t(message):s.premium?t('purchased'):!s.supported?t('nativeOnly'):'';
  for(const select of dialog.querySelectorAll('select')){const key=select.dataset.cosmetic;select.previousElementSibling.textContent=t(key);select.value=selected[key];select.disabled=!s.premium||s.busy;for(const option of select.options)option.textContent=t(option.value);}apply();
 }
 async function action(op){pause();audio.interrupt();message='';refresh();const result=await commerce.request(op);message=result.code==='earned'?'closed':(op==='prepare'||op==='privacy')&&result.code==='error'?'adError':result.code;refresh();}
 $('premium-open').addEventListener('click',()=>{pause();message='';refresh();dialog.showModal();commerce.refresh();});$('premium-close').addEventListener('click',()=>dialog.close());
 for(const [id,op]of [['premium-buy','buy'],['premium-restore','restore'],['ads-prepare','prepare'],['ads-privacy','privacy']])$(id).addEventListener('click',()=>action(op));
 refresh();return {refresh};
}
